const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>FeeScale \u2014 Freelance Rate Calculator: Hourly, Day & Project Rates</title>\n<meta name=\"description\" content=\"FeeScale is a free freelance rate calculator. Turn your take-home income goal into survival, sustainable and walk-away rates \u2014 hourly, day, project and retainer \u2014 with tax, expenses, time off and scope-creep buffer built in.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<style>\n  html { scroll-behavior: smooth; }\n  body { font-family: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; }\n  input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; height: 6px; border-radius: 9999px; background: #374151; outline: none; }\n  input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 20px; height: 20px; border-radius: 50%; background: #F59E0B; cursor: pointer; border: 3px solid #111827; box-shadow: 0 0 0 1px #F59E0B; }\n  input[type=range]::-moz-range-thumb { width: 20px; height: 20px; border-radius: 50%; background: #F59E0B; cursor: pointer; border: 3px solid #111827; box-shadow: 0 0 0 1px #F59E0B; }\n  input[type=range].teal-range::-webkit-slider-thumb { background: #14B8A6; box-shadow: 0 0 0 1px #14B8A6; }\n  input[type=range].teal-range::-moz-range-thumb { background: #14B8A6; box-shadow: 0 0 0 1px #14B8A6; }\n  .num-input { background: #0B1220; border: 1px solid #374151; border-radius: 0.5rem; padding: 0.5rem 0.75rem; width: 100%; color: #F9FAFB; }\n  .num-input:focus { outline: none; border-color: #F59E0B; box-shadow: 0 0 0 2px rgba(245,158,11,.25); }\n  select.num-input { appearance: none; }\n  .tier-card { transition: transform .15s ease, box-shadow .15s ease; }\n  .tier-card:hover { transform: translateY(-2px); }\n  .faq-answer { display: none; }\n  .faq-item.open .faq-answer { display: block; }\n  .faq-item.open .faq-chev { transform: rotate(180deg); }\n  .faq-chev { transition: transform .2s ease; }\n  @media print { .no-print { display: none !important; } }\n</style>\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    { \"@type\": \"Question\", \"name\": \"How much should I charge as a freelancer?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Start from the annual take-home income you want, then gross it up: add your yearly business expenses and divide by one minus your effective income-tax rate. Divide that revenue target by your realistic annual billable hours (working days minus time off, times billable hours per day, times your utilization rate). The result is your sustainable hourly rate. FeeScale automates this entire freelance rate calculation, including survival and walk-away tiers.\" } },\n    { \"@type\": \"Question\", \"name\": \"How do I calculate my hourly rate from a salary target?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Take your target take-home pay, add annual business expenses, and divide by (1 - tax rate) to get the revenue you must earn. Then divide by billable hours per year. Example: $60,000 take-home + $4,800 expenses at 25% tax needs $86,400 of revenue; at 1,128 billable hours per year that is about $77 per hour. An hourly rate calculator for freelancers like FeeScale does this math instantly and converts it to day, project and retainer rates.\" } },\n    { \"@type\": \"Question\", \"name\": \"Should I charge hourly, daily, project-based, or on retainer?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Charge hourly when scope is uncertain, daily for on-site or intensive consulting days, project-based when deliverables are well defined (it rewards efficiency), and monthly retainer for ongoing availability. FeeScale's freelance day rate calculator and project rate calculator convert between all four units from one base rate, so your pricing stays consistent no matter how the client wants to buy.\" } },\n    { \"@type\": \"Question\", \"name\": \"What is a walk-away rate and why do I need one?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"A walk-away rate is the minimum rate below which you decline the work \u2014 typically 25-35% above your sustainable rate. It protects you from desperation pricing, signals value to clients, and gives you a hard floor in negotiations. FeeScale shows your walk-away rate next to survival and sustainable tiers so you always know your numbers before a sales call.\" } },\n    { \"@type\": \"Question\", \"name\": \"How do I account for taxes and expenses in my freelance rate?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Add up everything the business costs you per year \u2014 software, hardware, insurance, accounting, coworking, marketing \u2014 and add it to your take-home target before grossing up for income tax. Most freelancers forget expenses entirely and undercharge by 10-20%. FeeScale's itemized breakdown shows exactly how much of your gross revenue goes to tax, expenses, and your pocket.\" } },\n    { \"@type\": \"Question\", \"name\": \"How much buffer should I add for scope creep?\", \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Add a 10-20% scope-creep buffer to every fixed quote. Projects almost always expand: extra revision rounds, stakeholder feedback, and 'one small thing' requests. Quoting your base project rate plus an explicit buffer keeps you profitable when scope drifts, and you can frame it to clients as a fixed, all-inclusive price. FeeScale applies your chosen buffer to project and retainer quotes automatically.\" } }\n  ]\n}\n</script>\n</head>\n<body id=\"top\" class=\"bg-[#0B1220] text-slate-100 antialiased\">\n\n<!-- ============ STICKY HEADER ============ -->\n<header class=\"sticky top-0 z-50 bg-[#0B1220]/95 backdrop-blur border-b border-slate-800\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"text-2xl font-extrabold tracking-tight\">\n      <span class=\"text-amber-400\">Fee</span><span class=\"text-teal-400\">Scale</span>\n    </a>\n    <nav class=\"flex items-center gap-5 text-sm font-medium\">\n      <a href=\"#top\" class=\"text-slate-300 hover:text-amber-400 transition\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"text-slate-300 hover:text-amber-400 transition\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ============ HERO ============ -->\n<section class=\"relative overflow-hidden\">\n  <div class=\"absolute inset-0 bg-gradient-to-br from-amber-500/10 via-transparent to-teal-500/10 pointer-events-none\"></div>\n  <div class=\"relative mx-auto max-w-6xl px-4 sm:px-6 pt-10 pb-8 text-center\">\n    <span class=\"inline-flex items-center gap-1.5 rounded-full border border-teal-400/40 bg-teal-400/10 px-3.5 py-1.5 text-xs font-semibold tracking-wide text-teal-300 uppercase\">\n      <svg class=\"w-3.5 h-3.5\" fill=\"currentColor\" viewBox=\"0 0 20 20\"><path fill-rule=\"evenodd\" d=\"M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z\" clip-rule=\"evenodd\"/></svg>\n      Unlimited Free Usage\n    </span>\n    <h1 class=\"mt-4 text-3xl sm:text-5xl font-extrabold tracking-tight text-white\">\n      Freelance Rate <span class=\"text-amber-400\">Calculator</span>\n    </h1>\n    <p class=\"mt-3 max-w-2xl mx-auto text-slate-400 text-sm sm:text-base\">\n      Start with the take-home income you want. FeeScale grosses it up for tax and expenses,\n      divides by your real billable hours, and gives you three rates \u2014 survival, sustainable, walk-away \u2014\n      in hourly, day, project and retainer units.\n    </p>\n  </div>\n</section>\n\n<!-- TOP AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ TOOL ============ -->\n<main id=\"tool\" class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8\">\n  <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n\n    <!-- ===== LEFT: INPUT PANEL ===== -->\n    <section class=\"lg:col-span-4 bg-[#1F2937] border border-slate-700/60 rounded-2xl p-5 sm:p-6 h-fit lg:sticky lg:top-20\">\n      <div class=\"flex items-center justify-between mb-5\">\n        <h2 class=\"text-lg font-bold text-white\">Rate Builder</h2>\n        <span class=\"text-[10px] font-semibold uppercase tracking-widest text-amber-400 bg-amber-400/10 border border-amber-400/30 rounded-full px-2.5 py-1\">Free forever</span>\n      </div>\n\n      <div class=\"space-y-5\">\n        <div>\n          <label for=\"curSel\" class=\"block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5\">Currency</label>\n          <select id=\"curSel\" class=\"num-input\">\n            <option value=\"USD\">USD \u2014 US Dollar ($)</option>\n            <option value=\"EUR\">EUR \u2014 Euro (\u20ac)</option>\n            <option value=\"GBP\">GBP \u2014 British Pound (\u00a3)</option>\n            <option value=\"INR\">INR \u2014 Indian Rupee (\u20b9)</option>\n            <option value=\"AUD\">AUD \u2014 Australian Dollar (A$)</option>\n            <option value=\"CAD\">CAD \u2014 Canadian Dollar (C$)</option>\n          </select>\n        </div>\n\n        <div>\n          <label for=\"takeHome\" class=\"block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5\">Target take-home income <span class=\"text-slate-500 normal-case\">/ year</span></label>\n          <input id=\"takeHome\" type=\"number\" min=\"0\" step=\"500\" value=\"60000\" class=\"num-input text-lg font-semibold text-amber-300\">\n          <p class=\"mt-1 text-[11px] text-slate-500\">What you want in your pocket after tax &amp; expenses.</p>\n        </div>\n\n        <div>\n          <div class=\"flex items-center justify-between mb-1.5\">\n            <label for=\"taxRange\" class=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Income tax rate</label>\n            <span class=\"text-sm font-bold text-amber-300\"><span id=\"taxNum\">25</span>%</span>\n          </div>\n          <input id=\"taxRange\" type=\"range\" min=\"0\" max=\"50\" step=\"0.5\" value=\"25\">\n        </div>\n\n        <div>\n          <label for=\"expMonthly\" class=\"block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5\">Business expenses <span class=\"text-slate-500 normal-case\">/ month</span></label>\n          <input id=\"expMonthly\" type=\"number\" min=\"0\" step=\"25\" value=\"400\" class=\"num-input\">\n          <p class=\"mt-1 text-[11px] text-slate-500\">Software, hardware, insurance, accounting, coworking\u2026</p>\n        </div>\n\n        <div class=\"grid grid-cols-2 gap-3\">\n          <div>\n            <label for=\"daysOff\" class=\"block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5\">Days off / year</label>\n            <input id=\"daysOff\" type=\"number\" min=\"0\" max=\"365\" step=\"1\" value=\"25\" class=\"num-input\">\n          </div>\n          <div>\n            <label for=\"daysPerWeek\" class=\"block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5\">Work days / week</label>\n            <input id=\"daysPerWeek\" type=\"number\" min=\"1\" max=\"7\" step=\"1\" value=\"5\" class=\"num-input\">\n          </div>\n        </div>\n\n        <div>\n          <div class=\"flex items-center justify-between mb-1.5\">\n            <label for=\"hrsPerDay\" class=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Billable hours / day</label>\n            <span class=\"text-sm font-bold text-amber-300\"><span id=\"hrsNum\">6</span>h</span>\n          </div>\n          <input id=\"hrsPerDay\" type=\"range\" min=\"2\" max=\"12\" step=\"0.5\" value=\"6\">\n        </div>\n\n        <div class=\"rounded-xl border border-teal-400/30 bg-teal-400/5 p-4\">\n          <div class=\"flex items-center justify-between mb-1.5\">\n            <label for=\"utilRange\" class=\"text-xs font-semibold uppercase tracking-wider text-teal-300\">Billable utilization</label>\n            <span class=\"text-sm font-bold text-teal-300\"><span id=\"utilNum\">80</span>%</span>\n          </div>\n          <input id=\"utilRange\" type=\"range\" min=\"20\" max=\"100\" step=\"1\" value=\"80\" class=\"teal-range\">\n          <p class=\"mt-1.5 text-[11px] text-slate-500\">Share of your work hours that are actually billed. The rest is admin, marketing &amp; pitching.</p>\n        </div>\n\n        <div>\n          <div class=\"flex items-center justify-between mb-1.5\">\n            <label for=\"bufferRange\" class=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Scope-creep buffer</label>\n            <span class=\"text-sm font-bold text-amber-300\">+<span id=\"bufferNum\">15</span>%</span>\n          </div>\n          <input id=\"bufferRange\" type=\"range\" min=\"0\" max=\"50\" step=\"1\" value=\"15\">\n        </div>\n\n        <div>\n          <label for=\"projHours\" class=\"block text-xs font-semibold uppercase tracking-wider text-slate-400 mb-1.5\">Typical project size <span class=\"text-slate-500 normal-case\">(hours)</span></label>\n          <input id=\"projHours\" type=\"number\" min=\"1\" step=\"1\" value=\"40\" class=\"num-input\">\n        </div>\n\n        <div id=\"warnBox\" class=\"hidden rounded-xl border border-red-400/40 bg-red-400/10 p-3 text-xs text-red-300\"></div>\n\n        <div class=\"pt-1\">\n          <div class=\"rounded-xl bg-[#0B1220] border border-slate-700 p-3.5 text-xs text-slate-400 leading-relaxed\">\n            <span class=\"font-semibold text-slate-200\">How it's computed:</span>\n            revenue = (take-home + expenses) \u00f7 (1 \u2212 tax) \u2192 hourly = revenue \u00f7 billable hours/yr.\n            Survival = 70% of target \u00b7 Sustainable = 100% \u00b7 Walk-away = 130%.\n          </div>\n        </div>\n\n        <button id=\"resetBtn\" class=\"w-full rounded-xl border border-slate-600 text-slate-300 text-sm font-semibold py-2.5 hover:border-amber-400 hover:text-amber-300 transition\">Reset to defaults</button>\n      </div>\n    </section>\n\n    <!-- ===== RIGHT: RESULTS ===== -->\n    <section class=\"lg:col-span-8 space-y-6\">\n\n      <!-- Tier cards -->\n      <div>\n        <h2 class=\"text-lg font-bold text-white mb-1\">Your three rates</h2>\n        <p class=\"text-xs text-slate-500 mb-4\">Quoted project &amp; retainer rates include your <span id=\"bufferEcho\" class=\"text-amber-300 font-semibold\">15%</span> scope buffer.</p>\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n\n          <div class=\"tier-card rounded-2xl border border-slate-700 bg-[#1F2937] p-5\">\n            <div class=\"flex items-center justify-between\">\n              <h3 class=\"text-sm font-bold uppercase tracking-widest text-slate-400\">Survival</h3>\n              <span class=\"text-[10px] font-semibold text-slate-500\">70% of target</span>\n            </div>\n            <div class=\"mt-2 text-3xl font-extrabold text-slate-200\"><span id=\"tSurvHourly\">\u2014</span><span class=\"text-sm font-medium text-slate-500\">/hr</span></div>\n            <p class=\"mt-1 text-[11px] text-slate-500\">Take-home target: <span id=\"tSurvTarget\" class=\"text-slate-300 font-semibold\">\u2014</span>/yr</p>\n            <dl class=\"mt-4 space-y-2 text-sm\">\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Day</dt><dd id=\"tSurvDay\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Project</dt><dd id=\"tSurvProj\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Project (quoted)</dt><dd id=\"tSurvProjQ\" class=\"font-semibold text-teal-300\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Retainer / mo</dt><dd id=\"tSurvRet\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n            </dl>\n          </div>\n\n          <div class=\"tier-card rounded-2xl border-2 border-amber-400 bg-[#1F2937] p-5 shadow-[0_0_30px_rgba(245,158,11,0.15)] relative\">\n            <span class=\"absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-amber-400 text-[#1F2937] text-[10px] font-extrabold uppercase tracking-widest px-3 py-1\">Recommended</span>\n            <div class=\"flex items-center justify-between\">\n              <h3 class=\"text-sm font-bold uppercase tracking-widest text-amber-400\">Sustainable</h3>\n              <span class=\"text-[10px] font-semibold text-slate-500\">100% of target</span>\n            </div>\n            <div class=\"mt-2 text-3xl font-extrabold text-amber-300\"><span id=\"tSustHourly\">\u2014</span><span class=\"text-sm font-medium text-slate-500\">/hr</span></div>\n            <p class=\"mt-1 text-[11px] text-slate-500\">Take-home target: <span id=\"tSustTarget\" class=\"text-slate-300 font-semibold\">\u2014</span>/yr</p>\n            <dl class=\"mt-4 space-y-2 text-sm\">\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Day</dt><dd id=\"tSustDay\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Project</dt><dd id=\"tSustProj\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Project (quoted)</dt><dd id=\"tSustProjQ\" class=\"font-semibold text-teal-300\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Retainer / mo</dt><dd id=\"tSustRet\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n            </dl>\n          </div>\n\n          <div class=\"tier-card rounded-2xl border border-teal-400/50 bg-[#1F2937] p-5\">\n            <div class=\"flex items-center justify-between\">\n              <h3 class=\"text-sm font-bold uppercase tracking-widest text-teal-300\">Walk-away</h3>\n              <span class=\"text-[10px] font-semibold text-slate-500\">130% of target</span>\n            </div>\n            <div class=\"mt-2 text-3xl font-extrabold text-teal-300\"><span id=\"tWalkHourly\">\u2014</span><span class=\"text-sm font-medium text-slate-500\">/hr</span></div>\n            <p class=\"mt-1 text-[11px] text-slate-500\">Take-home target: <span id=\"tWalkTarget\" class=\"text-slate-300 font-semibold\">\u2014</span>/yr</p>\n            <dl class=\"mt-4 space-y-2 text-sm\">\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Day</dt><dd id=\"tWalkDay\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Project</dt><dd id=\"tWalkProj\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Project (quoted)</dt><dd id=\"tWalkProjQ\" class=\"font-semibold text-teal-300\">\u2014</dd></div>\n              <div class=\"flex justify-between\"><dt class=\"text-slate-500\">Retainer / mo</dt><dd id=\"tWalkRet\" class=\"font-semibold text-slate-200\">\u2014</dd></div>\n            </dl>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- Converter + Quick quote -->\n      <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n        <div class=\"rounded-2xl border border-slate-700 bg-[#1F2937] p-5\">\n          <h3 class=\"text-sm font-bold text-white mb-1\">Unit converter</h3>\n          <p class=\"text-[11px] text-slate-500 mb-4\">Convert any rate between hourly, day, project &amp; retainer.</p>\n          <div class=\"flex gap-2\">\n            <input id=\"convAmount\" type=\"number\" min=\"0\" step=\"any\" value=\"500\" class=\"num-input\" aria-label=\"Amount to convert\">\n            <select id=\"convFrom\" class=\"num-input max-w-[7.5rem]\" aria-label=\"From unit\">\n              <option value=\"hour\">/ hour</option>\n              <option value=\"day\" selected>/ day</option>\n              <option value=\"project\">/ project</option>\n              <option value=\"retainer\">/ month</option>\n            </select>\n          </div>\n          <label class=\"mt-3 flex items-center gap-2 text-xs text-slate-400 cursor-pointer\">\n            <input id=\"convBufferChk\" type=\"checkbox\" class=\"w-4 h-4 accent-amber-400\" checked>\n            Apply scope buffer to project &amp; retainer\n          </label>\n          <div id=\"convOut\" class=\"mt-4 grid grid-cols-2 gap-2 text-sm\"></div>\n        </div>\n\n        <div class=\"rounded-2xl border border-slate-700 bg-[#1F2937] p-5\">\n          <h3 class=\"text-sm font-bold text-white mb-1\">Quick quote</h3>\n          <p class=\"text-[11px] text-slate-500 mb-4\">Enter estimated hours \u2192 price at each tier, buffer included.</p>\n          <div class=\"flex items-center gap-2\">\n            <input id=\"quoteHours\" type=\"number\" min=\"0\" step=\"1\" value=\"40\" class=\"num-input\" aria-label=\"Estimated hours\">\n            <span class=\"text-sm text-slate-500 whitespace-nowrap\">hours</span>\n          </div>\n          <div id=\"quoteOut\" class=\"mt-4 space-y-2.5 text-sm\"></div>\n        </div>\n      </div>\n\n      <!-- Itemized breakdown -->\n      <div class=\"rounded-2xl border border-slate-700 bg-[#1F2937] p-5 sm:p-6\">\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4\">\n          <h3 class=\"text-sm font-bold text-white\">Where the money goes <span class=\"text-slate-500 font-normal\">\u2014 itemized breakdown</span></h3>\n          <div class=\"flex rounded-lg overflow-hidden border border-slate-700 text-xs font-semibold\" role=\"tablist\" aria-label=\"Breakdown tier\">\n            <button id=\"bdTabSurv\" class=\"px-3 py-1.5 text-slate-400 hover:text-white\" role=\"tab\">Survival</button>\n            <button id=\"bdTabSust\" class=\"px-3 py-1.5 bg-amber-400 text-[#1F2937]\" role=\"tab\">Sustainable</button>\n            <button id=\"bdTabWalk\" class=\"px-3 py-1.5 text-slate-400 hover:text-white\" role=\"tab\">Walk-away</button>\n          </div>\n        </div>\n        <div class=\"h-4 rounded-full overflow-hidden flex bg-[#0B1220] border border-slate-700\">\n          <div id=\"bdBarTax\" class=\"bg-red-400/80\" style=\"width:25%\"></div>\n          <div id=\"bdBarExp\" class=\"bg-teal-400/80\" style=\"width:6%\"></div>\n          <div id=\"bdBarTake\" class=\"bg-amber-400/90\" style=\"width:69%\"></div>\n        </div>\n        <div class=\"mt-4 grid grid-cols-2 sm:grid-cols-4 gap-3 text-sm\">\n          <div class=\"rounded-xl bg-[#0B1220] border border-slate-700 p-3\">\n            <div class=\"text-[11px] uppercase tracking-wider text-slate-500\">Gross revenue</div>\n            <div id=\"bdGross\" class=\"mt-1 text-lg font-extrabold text-white\">\u2014</div>\n          </div>\n          <div class=\"rounded-xl bg-[#0B1220] border border-slate-700 p-3\">\n            <div class=\"text-[11px] uppercase tracking-wider text-slate-500\">Income tax <span id=\"bdTaxPct\" class=\"text-red-300\">25%</span></div>\n            <div id=\"bdTax\" class=\"mt-1 text-lg font-extrabold text-red-300\">\u2014</div>\n          </div>\n          <div class=\"rounded-xl bg-[#0B1220] border border-slate-700 p-3\">\n            <div class=\"text-[11px] uppercase tracking-wider text-slate-500\">Expenses</div>\n            <div id=\"bdExp\" class=\"mt-1 text-lg font-extrabold text-teal-300\">\u2014</div>\n          </div>\n          <div class=\"rounded-xl bg-[#0B1220] border border-slate-700 p-3\">\n            <div class=\"text-[11px] uppercase tracking-wider text-slate-500\">Your take-home</div>\n            <div id=\"bdTake\" class=\"mt-1 text-lg font-extrabold text-amber-300\">\u2014</div>\n          </div>\n        </div>\n        <p class=\"mt-3 text-[11px] text-slate-500\">Based on <span id=\"bdHours\" class=\"text-slate-300 font-semibold\">\u2014</span> billable hours / year at <span id=\"bdUtil\" class=\"text-slate-300 font-semibold\">\u2014</span> utilization.</p>\n      </div>\n\n    </section>\n  </div>\n\n  <!-- ===== SUMMARY STRIP ===== -->\n  <section class=\"mt-6 rounded-2xl border border-amber-400/40 bg-gradient-to-r from-[#1F2937] via-[#1F2937] to-[#1F2937] p-5 sm:p-6\">\n    <div class=\"flex flex-wrap items-center justify-between gap-3 mb-3\">\n      <h3 class=\"text-sm font-bold text-white\">Copy-ready rate summary</h3>\n      <div class=\"flex flex-wrap items-center gap-2\">\n        <input id=\"profileName\" type=\"text\" placeholder=\"Profile name\u2026\" maxlength=\"40\" class=\"num-input !w-40 text-sm\" aria-label=\"Profile name\">\n        <button id=\"saveProfileBtn\" class=\"rounded-lg bg-teal-500/15 border border-teal-400/50 text-teal-300 text-xs font-bold px-3 py-2 hover:bg-teal-500/25 transition\">Save profile</button>\n        <select id=\"profileSel\" class=\"num-input !w-40 text-sm\" aria-label=\"Saved profiles\"><option value=\"\">Saved profiles\u2026</option></select>\n        <button id=\"delProfileBtn\" class=\"rounded-lg border border-slate-600 text-slate-400 text-xs font-bold px-3 py-2 hover:border-red-400 hover:text-red-300 transition\">Delete</button>\n      </div>\n    </div>\n    <pre id=\"summaryText\" class=\"whitespace-pre-wrap rounded-xl bg-[#0B1220] border border-slate-700 p-4 text-xs sm:text-sm text-slate-300 font-mono leading-relaxed\"></pre>\n    <div class=\"mt-3 flex items-center gap-3\">\n      <button id=\"copyBtn\" class=\"rounded-xl bg-amber-400 text-[#1F2937] text-sm font-extrabold px-5 py-2.5 hover:bg-amber-300 transition\">Copy summary</button>\n      <span id=\"copyMsg\" class=\"text-xs text-teal-300 opacity-0 transition-opacity\">Copied to clipboard \u2713</span>\n    </div>\n  </section>\n</main>\n\n<!-- BOTTOM AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ============ SEO ARTICLE ============ -->\n<article id=\"seo-article\" class=\"mx-auto max-w-4xl px-4 sm:px-6 py-10 text-slate-300\">\n  <h2 class=\"text-2xl sm:text-3xl font-extrabold text-white tracking-tight\">Freelance Rate Calculator: How to Price Your Work So You Actually Take Home What You Want</h2>\n  <p class=\"mt-4 text-sm sm:text-base leading-relaxed\">Ask a room of freelancers how much to charge as a freelancer and you will hear everything from confident six-figure hourly numbers to embarrassed silence. Pricing is the single hardest business decision an independent worker makes, and most people get it wrong \u2014 usually by undercharging. A freelance rate calculator removes the guesswork: instead of copying a competitor's number or picking a figure that \"sounds reasonable,\" you start from the income you want to take home and work backwards through taxes, expenses, time off, and non-billable hours. This guide explains the full method behind FeeScale's hourly rate calculator for freelancers, so you understand every number on the screen \u2014 and can defend your quotes with confidence.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Why most freelancers undercharge</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">The classic mistake is converting a salary directly into an hourly rate: divide a $60,000 salary by 2,080 working hours and charge $29 an hour. That math quietly ignores four realities. First, a salary already has taxes withheld and benefits paid by an employer; a freelancer pays all of that themselves. Second, employees get paid holidays, sick days, and slow weeks \u2014 freelancers bill only the hours clients actually pay for. Third, running a business costs money: software subscriptions, a decent laptop, accounting, insurance, marketing, and a workspace all come out of your revenue. Fourth, a large slice of every freelancer's week \u2014 pitching, admin, invoicing, learning \u2014 is never billed to anyone. Skip any one of these and your \"rate\" quietly becomes a pay cut. An honest freelance rate calculation accounts for all four before a single quote goes out.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Start with your take-home target, not your hourly rate</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">The most reliable way to answer \"how much should I charge?\" is to flip the question: how much do you want to keep? Pick an annual take-home number that covers your life \u2014 rent, food, savings, the holiday you keep postponing \u2014 and treat it as the non-negotiable output of the whole exercise. Everything else is a cost layered on top. This target-first approach is why FeeScale asks for take-home income before anything else: your rate is then whatever number delivers that life, not whatever the market happens to whisper. If the resulting rate feels high, the answer is rarely to shrink your target; it is to find better clients, sharper positioning, or a more valuable offer.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">The gross-up: taxes and expenses eat first</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">Revenue is not income. Before a dollar reaches your pocket, two claims are settled: the tax authority and your business itself. Suppose you want $60,000 take-home, spend $400 a month on business expenses ($4,800 a year), and face an effective income-tax rate of 25%. The revenue you must earn is not $64,800 \u2014 because tax is charged on revenue, not on what's left. The correct formula is revenue = (take-home + expenses) \u00f7 (1 \u2212 tax rate), which gives ($60,000 + $4,800) \u00f7 0.75 = $86,400. That extra $21,600 is invisible in salary thinking and is exactly where undercharging hides. List every business expense honestly: tools, hosting, devices, professional insurance, an accountant, courses, coworking, even the coffee you buy to work from caf\u00e9s. Most freelancers discover their real costs are 10\u201320% higher than their first guess, and every missing dollar comes straight out of their own pay.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Time off is a business cost too</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">Employees get roughly 20\u201330 paid days off a year without thinking about it. Freelancers who forget to price in their own holidays, sick days, and family time end up funding their vacations out of thin air. A freelance day rate calculator should subtract your days off before computing billable capacity: with a five-day week (260 working days) minus 25 days off, you have 235 potential workdays \u2014 and every one of them has to carry the revenue target. Be generous here. A rate built on zero holidays is a rate that chains you to your desk, and burnout is the most expensive business cost of all.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Utilization: you will not bill 100% of your hours</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">Billable utilization is the percentage of your work hours that clients actually pay for. The rest goes to proposals, discovery calls that go nowhere, admin, bookkeeping, marketing, and keeping your skills sharp. New freelancers often assume 90\u2013100% utilization; experienced ones plan for 60\u201380%. The difference is enormous: at 1,410 potential hours a year, dropping from 100% to 80% utilization cuts billable hours to 1,128, which raises the required hourly rate by 25%. That is not pessimism \u2014 it is the honest price of running a one-person business. FeeScale's utilization slider lets you feel this trade-off instantly: drag it down and watch your sustainable rate climb, because fewer billable hours must carry the same annual target.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Three tiers: survival, sustainable, and walk-away rates</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">One rate is not enough, because not every situation deserves the same price. FeeScale computes three tiers from your inputs. The <strong class=\"text-white\">survival rate</strong> covers 70% of your take-home target plus full taxes and expenses \u2014 your absolute floor for slow months or strategic low-margin work. Never quote below it; work priced under survival literally costs you money. The <strong class=\"text-white\">sustainable rate</strong> delivers 100% of your target and is your default quote: the number that makes freelancing a genuinely good living, not a stressful hobby. The <strong class=\"text-white\">walk-away rate</strong> sits at 130% of target and is your negotiation anchor \u2014 the price below which you politely decline. Having all three visible before a sales call changes the conversation: instead of nervously naming a number, you know your floor, your fair price, and your premium, and you can move between them deliberately.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Hourly, day, project, or retainer: picking the right unit</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">The same underlying rate can be sold four ways, and the unit you choose shapes client psychology. <strong class=\"text-white\">Hourly</strong> suits uncertain scope \u2014 maintenance, consulting, research \u2014 because the meter matches the work. <strong class=\"text-white\">Day rates</strong> work for intensive on-site or workshop engagements; a day rate is simply your hourly rate times billable hours per day, and clients love its simplicity. <strong class=\"text-white\">Project rates</strong> reward efficiency: quote a fixed price for defined deliverables and faster work means a higher effective hourly rate \u2014 just make sure scope is written down. <strong class=\"text-white\">Retainers</strong> trade a small discount for predictable monthly income, the holy grail of freelancing; price them as your hourly rate times monthly billable hours. A good project rate calculator keeps all four consistent so you never accidentally discount yourself by switching units \u2014 which is exactly what FeeScale's converter does.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">The scope-creep buffer: quote for the project you'll actually deliver</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">Nearly every fixed-price project expands: an extra revision round, a stakeholder who appears in week three, \"one small thing\" that is never small. Freelancers who quote their raw costed hours absorb all of that for free, watching their effective hourly rate melt. The professional fix is a scope-creep buffer of 10\u201320% baked into every quote. It is not padding or dishonesty \u2014 it is the actuarial price of reality, and you can present it to clients as a fixed, all-inclusive price that protects them from surprise invoices too. FeeScale applies your chosen buffer to project and retainer quotes automatically, so the number you copy into a proposal already includes the messiness of real projects.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Raising your rates without losing clients</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">Rates are not tattoos; review them every six months. If your calendar is full for the next two months, your rates are too low \u2014 scarcity should raise prices, not just lengthen your hours. Raise rates for new clients first, then grandfather existing ones with 30\u201360 days' notice and a clear explanation tied to demand and results, not apologies. Productize what you can: defined packages with fixed project rates convert better than open-ended hourly billing and make increases feel natural. And keep your walk-away rate sacred \u2014 every project accepted below it teaches the market (and yourself) that your floor is negotiable. Over a career, the freelancers who earn the most are rarely the most talented; they are the ones who priced like a business from day one.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">A worked example</h3>\n  <p class=\"mt-3 text-sm sm:text-base leading-relaxed\">Let's run the full freelance rate calculation with realistic numbers. Target take-home: $60,000 a year. Business expenses: $400 a month ($4,800 a year). Effective tax rate: 25%. Required revenue = ($60,000 + $4,800) \u00f7 0.75 = $86,400. Time: five-day weeks minus 25 days off = 235 workdays; at 6 billable hours a day and 80% utilization, that's 1,128 billable hours a year. Sustainable hourly rate = $86,400 \u00f7 1,128 \u2248 $77/hour. Day rate (6 hours) \u2248 $460. A typical 40-hour project \u2248 $3,064, or $3,523 quoted with a 15% scope buffer. Monthly retainer \u2248 $7,200. The survival floor lands near $55/hour and the walk-away rate near $98/hour. Notice how far this is from the na\u00efve $29/hour salary conversion \u2014 that gap is the difference between a hobby and a business, and it is why doing the math properly matters more than any single pricing tactic.</p>\n\n  <h3 class=\"mt-8 text-xl font-bold text-white\">Frequently asked questions</h3>\n  <div class=\"mt-4 space-y-3\">\n    <div class=\"faq-item rounded-xl border border-slate-700 bg-[#1F2937]\">\n      <button class=\"faq-q w-full flex items-center justify-between gap-3 text-left px-5 py-4 font-semibold text-white text-sm sm:text-base\">How much should I charge as a freelancer?<svg class=\"faq-chev w-5 h-5 shrink-0 text-amber-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg></button>\n      <p class=\"faq-answer px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Start from the annual take-home income you want, add yearly business expenses, and divide by one minus your effective tax rate to get required revenue. Divide that by your realistic annual billable hours (workdays minus time off, times billable hours per day, times utilization). The result is your sustainable rate \u2014 FeeScale's freelance rate calculator does this in seconds and shows survival and walk-away tiers alongside it.</p>\n    </div>\n    <div class=\"faq-item rounded-xl border border-slate-700 bg-[#1F2937]\">\n      <button class=\"faq-q w-full flex items-center justify-between gap-3 text-left px-5 py-4 font-semibold text-white text-sm sm:text-base\">How do I calculate my hourly rate from a salary target?<svg class=\"faq-chev w-5 h-5 shrink-0 text-amber-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg></button>\n      <p class=\"faq-answer px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Never just divide salary by 2,080 hours \u2014 that ignores tax, expenses, holidays, and non-billable time. Use the gross-up formula: (take-home + annual expenses) \u00f7 (1 \u2212 tax rate) \u00f7 billable hours per year. For example, $60,000 take-home with $4,800 expenses at 25% tax and 1,128 billable hours gives roughly $77/hour \u2014 nearly triple the na\u00efve conversion. An hourly rate calculator for freelancers applies this correctly every time.</p>\n    </div>\n    <div class=\"faq-item rounded-xl border border-slate-700 bg-[#1F2937]\">\n      <button class=\"faq-q w-full flex items-center justify-between gap-3 text-left px-5 py-4 font-semibold text-white text-sm sm:text-base\">Should I charge hourly, daily, project-based, or on retainer?<svg class=\"faq-chev w-5 h-5 shrink-0 text-amber-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg></button>\n      <p class=\"faq-answer px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Match the unit to the engagement: hourly for uncertain scope, day rates for intensive on-site work, fixed project pricing for well-defined deliverables (it rewards your efficiency), and monthly retainers for ongoing availability. Keep all four derived from one base hourly rate so switching units never accidentally discounts you \u2014 FeeScale's freelance day rate calculator and project rate calculator handle the conversions.</p>\n    </div>\n    <div class=\"faq-item rounded-xl border border-slate-700 bg-[#1F2937]\">\n      <button class=\"faq-q w-full flex items-center justify-between gap-3 text-left px-5 py-4 font-semibold text-white text-sm sm:text-base\">What is a walk-away rate and why do I need one?<svg class=\"faq-chev w-5 h-5 shrink-0 text-amber-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg></button>\n      <p class=\"faq-answer px-5 pb-5 text-sm text-slate-400 leading-relaxed\">A walk-away rate is the minimum price below which you decline the work \u2014 typically about 30% above your sustainable rate. It stops desperation pricing, anchors negotiations in your favor, and protects your positioning. Decide it before the sales call, not during it; FeeScale displays it next to your survival and sustainable tiers so all three numbers are in front of you.</p>\n    </div>\n    <div class=\"faq-item rounded-xl border border-slate-700 bg-[#1F2937]\">\n      <button class=\"faq-q w-full flex items-center justify-between gap-3 text-left px-5 py-4 font-semibold text-white text-sm sm:text-base\">How do I account for taxes and expenses in my freelance rate?<svg class=\"faq-chev w-5 h-5 shrink-0 text-amber-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg></button>\n      <p class=\"faq-answer px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Total every annual business cost \u2014 software, hardware, insurance, accounting, marketing, workspace \u2014 add it to your take-home target, then gross up for income tax with revenue = (take-home + expenses) \u00f7 (1 \u2212 tax rate). Forgetting expenses is the most common pricing error and typically underprices you by 10\u201320%. FeeScale's itemized breakdown shows exactly how gross revenue splits into tax, expenses, and take-home.</p>\n    </div>\n    <div class=\"faq-item rounded-xl border border-slate-700 bg-[#1F2937]\">\n      <button class=\"faq-q w-full flex items-center justify-between gap-3 text-left px-5 py-4 font-semibold text-white text-sm sm:text-base\">How much buffer should I add for scope creep?<svg class=\"faq-chev w-5 h-5 shrink-0 text-amber-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19 9l-7 7-7-7\"/></svg></button>\n      <p class=\"faq-answer px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Add 10\u201320% to every fixed quote. Extra revisions, late-appearing stakeholders, and \"one small thing\" requests are the norm, not the exception. A buffer keeps you profitable when scope drifts and lets you offer clients a fixed, all-inclusive price with no surprise invoices. FeeScale's scope-creep buffer applies automatically to project and retainer quotes.</p>\n    </div>\n  </div>\n</article>\n\n<!-- ============ FOOTER ============ -->\n<footer class=\"border-t border-slate-800 mt-4\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-4\">\n    <div class=\"text-xl font-extrabold tracking-tight\"><span class=\"text-amber-400\">Fee</span><span class=\"text-teal-400\">Scale</span></div>\n    <p class=\"text-xs text-slate-500 text-center\">Free freelance rate calculator. Your inputs never leave your browser \u2014 no signup, no tracking.</p>\n    <nav class=\"flex items-center gap-5 text-sm font-medium\">\n      <a href=\"#top\" class=\"text-slate-400 hover:text-amber-400 transition\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"text-slate-400 hover:text-amber-400 transition\">More Tools</a>\n    </nav>\n  </div>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<script>\n/*__PURE_START__*/\nvar FS_TIER_TARGETS = { survival: 0.7, sustainable: 1.0, walkaway: 1.3 };\nvar FS_TIER_ORDER = ['survival', 'sustainable', 'walkaway'];\nvar FS_TIER_LABELS = { survival: 'Survival', sustainable: 'Sustainable', walkaway: 'Walk-away' };\nvar FS_CURRENCIES = {\n  USD: { symbol: '$',  label: 'USD' },\n  EUR: { symbol: '\\u20AC', label: 'EUR' },\n  GBP: { symbol: '\\u00A3', label: 'GBP' },\n  INR: { symbol: '\\u20B9', label: 'INR' },\n  AUD: { symbol: 'A$', label: 'AUD' },\n  CAD: { symbol: 'C$', label: 'CAD' }\n};\nvar FS_DEFAULTS = { currency: 'USD', takeHome: 60000, taxPct: 25, expensesMonthly: 400, daysOff: 25, daysPerWeek: 5, hrsPerDay: 6, utilization: 80, scopeBuffer: 15, projectHours: 40 };\nvar FS_PROFILE_KEY = 'feescale-profiles-v1';\n\nfunction fsToNum(v, dflt) { var n = parseFloat(v); return (typeof n === 'number' && isFinite(n)) ? n : dflt; }\nfunction fsClamp(v, min, max) { return Math.min(max, Math.max(min, v)); }\n\nfunction fsSanitize(raw) {\n  var r = raw || {};\n  var takeHome = Math.max(0, fsToNum(r.takeHome, FS_DEFAULTS.takeHome));\n  var taxPct = fsClamp(fsToNum(r.taxPct, FS_DEFAULTS.taxPct), 0, 99);\n  var expensesMonthly = Math.max(0, fsToNum(r.expensesMonthly, FS_DEFAULTS.expensesMonthly));\n  var daysOff = fsClamp(fsToNum(r.daysOff, FS_DEFAULTS.daysOff), 0, 365);\n  var daysPerWeek = fsClamp(fsToNum(r.daysPerWeek, FS_DEFAULTS.daysPerWeek), 1, 7);\n  var hrsPerDay = fsClamp(fsToNum(r.hrsPerDay, FS_DEFAULTS.hrsPerDay), 0.5, 16);\n  var utilization = fsClamp(fsToNum(r.utilization, FS_DEFAULTS.utilization), 0, 100);\n  var scopeBuffer = fsClamp(fsToNum(r.scopeBuffer, FS_DEFAULTS.scopeBuffer), 0, 100);\n  var projectHours = fsClamp(fsToNum(r.projectHours, FS_DEFAULTS.projectHours), 1, 2000);\n  var currency = FS_CURRENCIES[r.currency] ? r.currency : 'USD';\n  var expensesAnnual = expensesMonthly * 12;\n  var workDays = Math.max(0, daysPerWeek * 52 - daysOff);\n  var billableHours = workDays * hrsPerDay * (utilization / 100);\n  return { currency: currency, takeHome: takeHome, taxPct: taxPct, expensesMonthly: expensesMonthly,\n    expensesAnnual: expensesAnnual, daysOff: daysOff, daysPerWeek: daysPerWeek, hrsPerDay: hrsPerDay,\n    utilization: utilization, scopeBuffer: scopeBuffer, projectHours: projectHours,\n    workDays: workDays, billableHours: billableHours };\n}\n\nfunction fsGrossRequired(takeHome, taxPct, expensesAnnual) {\n  if (!(takeHome >= 0) || !(expensesAnnual >= 0)) return NaN;\n  if (!(taxPct >= 0) || !(taxPct < 100)) return NaN;\n  return (takeHome + expensesAnnual) / (1 - taxPct / 100);\n}\n\nfunction fsBreakdown(takeHome, taxPct, expensesAnnual) {\n  var gross = fsGrossRequired(takeHome, taxPct, expensesAnnual);\n  if (!isFinite(gross)) return null;\n  return { gross: gross, tax: gross * (taxPct / 100), expenses: expensesAnnual, takeHome: takeHome };\n}\n\nfunction fsTierRates(inp) {\n  var out = {};\n  for (var i = 0; i < FS_TIER_ORDER.length; i++) {\n    var tier = FS_TIER_ORDER[i];\n    var target = inp.takeHome * FS_TIER_TARGETS[tier];\n    var gross = fsGrossRequired(target, inp.taxPct, inp.expensesAnnual);\n    var hourly = (inp.billableHours > 0 && isFinite(gross)) ? gross / inp.billableHours : NaN;\n    var day = isFinite(hourly) ? hourly * inp.hrsPerDay : NaN;\n    var project = isFinite(hourly) ? hourly * inp.projectHours : NaN;\n    var retainer = isFinite(hourly) ? hourly * inp.billableHours / 12 : NaN;\n    var mult = 1 + inp.scopeBuffer / 100;\n    out[tier] = {\n      target: target, gross: gross, hourly: hourly, day: day, project: project, retainer: retainer,\n      projectQuoted: isFinite(project) ? project * mult : NaN,\n      retainerQuoted: isFinite(retainer) ? retainer * mult : NaN,\n      breakdown: fsBreakdown(target, inp.taxPct, inp.expensesAnnual)\n    };\n  }\n  return out;\n}\n\nfunction fsUnitHours(inp) {\n  return { hour: 1, day: inp.hrsPerDay, project: inp.projectHours, retainer: inp.billableHours / 12 };\n}\n\nfunction fsConvert(amount, fromUnit, toUnit, inp) {\n  var uh = fsUnitHours(inp);\n  if (!(amount >= 0) || !uh[fromUnit] || !uh[toUnit]) return NaN;\n  return amount * uh[toUnit] / uh[fromUnit];\n}\n\nfunction fsQuote(hours, inp) {\n  var tiers = fsTierRates(inp);\n  var out = {};\n  for (var i = 0; i < FS_TIER_ORDER.length; i++) {\n    var t = FS_TIER_ORDER[i];\n    var base = isFinite(tiers[t].hourly) ? tiers[t].hourly * hours : NaN;\n    out[t] = { base: base, quoted: isFinite(base) ? base * (1 + inp.scopeBuffer / 100) : NaN };\n  }\n  return out;\n}\n\nfunction fsMoney(n, currency) {\n  if (!isFinite(n)) return '\\u2014';\n  var sym = (FS_CURRENCIES[currency] || FS_CURRENCIES.USD).symbol;\n  return sym + Math.round(n).toLocaleString('en-US');\n}\nfunction fsMoney2(n, currency) {\n  if (!isFinite(n)) return '\\u2014';\n  var sym = (FS_CURRENCIES[currency] || FS_CURRENCIES.USD).symbol;\n  return sym + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n}\n\nfunction fsCopySummary(inp, tiers) {\n  var s = tiers.sustainable, v = tiers.survival, w = tiers.walkaway;\n  var L = [];\n  L.push('My freelance rates (calculated with FeeScale):');\n  L.push('\\u2022 Hourly: ' + fsMoney2(s.hourly, inp.currency) + '/hr  (survival floor ' + fsMoney2(v.hourly, inp.currency) + ' \\u00B7 walk-away ' + fsMoney2(w.hourly, inp.currency) + ')');\n  L.push('\\u2022 Day rate (' + inp.hrsPerDay + 'h): ' + fsMoney(s.day, inp.currency) + '/day');\n  L.push('\\u2022 Project (' + inp.projectHours + 'h): ' + fsMoney(s.project, inp.currency) + ' \\u2014 quoted ' + fsMoney(s.projectQuoted, inp.currency) + ' incl. ' + inp.scopeBuffer + '% scope buffer');\n  L.push('\\u2022 Monthly retainer: ' + fsMoney(s.retainer, inp.currency) + '/mo');\n  L.push('Assumptions: ' + fsMoney(inp.takeHome, inp.currency) + '/yr take-home target, ' + inp.taxPct + '% income tax, ' +\n    fsMoney(inp.expensesAnnual, inp.currency) + '/yr expenses, ' + Math.round(inp.billableHours).toLocaleString('en-US') +\n    ' billable hrs/yr (' + inp.utilization + '% utilization, ' + Math.round(inp.workDays) + ' workdays).');\n  return L.join('\\n');\n}\n/*__PURE_END__*/\n\n/* ================= UI WIRING (DOM only, not part of pure logic) ================= */\n(function () {\n  'use strict';\n  function $(id) { return document.getElementById(id); }\n  var INPUT_IDS = ['curSel','takeHome','taxRange','expMonthly','daysOff','daysPerWeek','hrsPerDay','utilRange','bufferRange','projHours'];\n  var bdTier = 'sustainable';\n\n  function readInputs() {\n    return {\n      currency: $('curSel').value,\n      takeHome: $('takeHome').value,\n      taxPct: $('taxRange').value,\n      expensesMonthly: $('expMonthly').value,\n      daysOff: $('daysOff').value,\n      daysPerWeek: $('daysPerWeek').value,\n      hrsPerDay: $('hrsPerDay').value,\n      utilization: $('utilRange').value,\n      scopeBuffer: $('bufferRange').value,\n      projectHours: $('projHours').value\n    };\n  }\n\n  function setTier(prefix, t) {\n    $('t' + prefix + 'Hourly').textContent = fsMoney2(t.hourly, lastInp.currency);\n    $('t' + prefix + 'Target').textContent = fsMoney(t.target, lastInp.currency);\n    $('t' + prefix + 'Day').textContent = fsMoney(t.day, lastInp.currency) + '/day';\n    $('t' + prefix + 'Proj').textContent = fsMoney(t.project, lastInp.currency);\n    $('t' + prefix + 'ProjQ').textContent = fsMoney(t.projectQuoted, lastInp.currency);\n    $('t' + prefix + 'Ret').textContent = fsMoney(t.retainer, lastInp.currency) + '/mo';\n  }\n\n  var lastInp = null, lastTiers = null;\n\n  function render() {\n    lastInp = fsSanitize(readInputs());\n    lastTiers = fsTierRates(lastInp);\n    var inp = lastInp, cur = inp.currency;\n\n    // slider readouts\n    $('taxNum').textContent = inp.taxPct;\n    $('hrsNum').textContent = inp.hrsPerDay;\n    $('utilNum').textContent = inp.utilization;\n    $('bufferNum').textContent = inp.scopeBuffer;\n    $('bufferEcho').textContent = inp.scopeBuffer + '%';\n\n    // warnings\n    var warn = $('warnBox');\n    if (inp.billableHours <= 0) {\n      warn.classList.remove('hidden');\n      warn.textContent = 'Billable hours are zero \u2014 raise utilization or billable hours/day, or reduce days off.';\n    } else if (inp.utilization < 40) {\n      warn.classList.remove('hidden');\n      warn.textContent = 'Very low utilization (' + inp.utilization + '%) pushes rates high \u2014 typical freelancers bill 60\u201380% of work hours.';\n    } else { warn.classList.add('hidden'); }\n\n    // tier cards\n    setTier('Surv', lastTiers.survival);\n    setTier('Sust', lastTiers.sustainable);\n    setTier('Walk', lastTiers.walkaway);\n\n    renderConverter();\n    renderQuote();\n    renderBreakdown();\n    $('summaryText').textContent = fsCopySummary(inp, lastTiers);\n  }\n\n  var UNIT_LABELS = { hour: '/hour', day: '/day', project: '/project', retainer: '/month' };\n  function renderConverter() {\n    var inp = lastInp, cur = inp.currency;\n    var amt = fsToNum($('convAmount').value, 0);\n    var from = $('convFrom').value;\n    var applyBuf = $('convBufferChk').checked;\n    var mult = 1 + inp.scopeBuffer / 100;\n    var box = $('convOut');\n    box.innerHTML = '';\n    ['hour','day','project','retainer'].forEach(function (u) {\n      var val = fsConvert(amt, from, u, inp);\n      if (applyBuf && (u === 'project' || u === 'retainer') && isFinite(val)) val *= mult;\n      var cell = document.createElement('div');\n      cell.className = 'rounded-lg bg-[#0B1220] border border-slate-700 px-3 py-2.5';\n      cell.innerHTML = '<div class=\"text-[10px] uppercase tracking-wider text-slate-500\">' + u + '</div>' +\n        '<div class=\"font-bold ' + (u === from ? 'text-teal-300' : 'text-white') + '\">' + fsMoney(val, cur) +\n        '<span class=\"text-[10px] font-normal text-slate-500\">' + UNIT_LABELS[u] + '</span></div>';\n      box.appendChild(cell);\n    });\n  }\n\n  function renderQuote() {\n    var inp = lastInp, cur = inp.currency;\n    var hours = fsToNum($('quoteHours').value, 0);\n    var q = fsQuote(hours, inp);\n    var box = $('quoteOut');\n    box.innerHTML = '';\n    FS_TIER_ORDER.forEach(function (t) {\n      var row = document.createElement('div');\n      var color = t === 'sustainable' ? 'text-amber-300' : (t === 'walkaway' ? 'text-teal-300' : 'text-slate-300');\n      row.className = 'flex items-center justify-between rounded-lg bg-[#0B1220] border border-slate-700 px-3 py-2.5';\n      row.innerHTML = '<span class=\"text-xs font-semibold uppercase tracking-wider text-slate-500\">' + FS_TIER_LABELS[t] + '</span>' +\n        '<span class=\"text-right\"><span class=\"' + color + ' font-bold\">' + fsMoney(q[t].quoted, cur) + '</span>' +\n        '<span class=\"block text-[10px] text-slate-500\">base ' + fsMoney(q[t].base, cur) + ' + ' + inp.scopeBuffer + '% buffer</span></span>';\n      box.appendChild(row);\n    });\n  }\n\n  function renderBreakdown() {\n    var inp = lastInp, cur = inp.currency;\n    var t = lastTiers[bdTier];\n    var b = t.breakdown;\n    if (!b) return;\n    $('bdGross').textContent = fsMoney(b.gross, cur);\n    $('bdTax').textContent = fsMoney(b.tax, cur);\n    $('bdTaxPct').textContent = inp.taxPct + '%';\n    $('bdExp').textContent = fsMoney(b.expenses, cur);\n    $('bdTake').textContent = fsMoney(b.takeHome, cur);\n    var g = b.gross || 1;\n    $('bdBarTax').style.width = (b.tax / g * 100).toFixed(1) + '%';\n    $('bdBarExp').style.width = (b.expenses / g * 100).toFixed(1) + '%';\n    $('bdBarTake').style.width = (b.takeHome / g * 100).toFixed(1) + '%';\n    $('bdHours').textContent = Math.round(inp.billableHours).toLocaleString('en-US');\n    $('bdUtil').textContent = inp.utilization + '%';\n    // tab styles\n    [['bdTabSurv','survival'],['bdTabSust','sustainable'],['bdTabWalk','walkaway']].forEach(function (p) {\n      var el = $(p[0]);\n      if (p[1] === bdTier) { el.className = 'px-3 py-1.5 bg-amber-400 text-[#1F2937]'; }\n      else { el.className = 'px-3 py-1.5 text-slate-400 hover:text-white'; }\n    });\n  }\n\n  // events\n  INPUT_IDS.forEach(function (id) { $(id).addEventListener('input', render); });\n  ['convAmount','convFrom'].forEach(function (id) { $(id).addEventListener('input', renderConverter); });\n  $('convBufferChk').addEventListener('change', renderConverter);\n  $('quoteHours').addEventListener('input', renderQuote);\n  $('bdTabSurv').addEventListener('click', function () { bdTier = 'survival'; renderBreakdown(); });\n  $('bdTabSust').addEventListener('click', function () { bdTier = 'sustainable'; renderBreakdown(); });\n  $('bdTabWalk').addEventListener('click', function () { bdTier = 'walkaway'; renderBreakdown(); });\n\n  $('resetBtn').addEventListener('click', function () {\n    $('curSel').value = FS_DEFAULTS.currency;\n    $('takeHome').value = FS_DEFAULTS.takeHome;\n    $('taxRange').value = FS_DEFAULTS.taxPct;\n    $('expMonthly').value = FS_DEFAULTS.expensesMonthly;\n    $('daysOff').value = FS_DEFAULTS.daysOff;\n    $('daysPerWeek').value = FS_DEFAULTS.daysPerWeek;\n    $('hrsPerDay').value = FS_DEFAULTS.hrsPerDay;\n    $('utilRange').value = FS_DEFAULTS.utilization;\n    $('bufferRange').value = FS_DEFAULTS.scopeBuffer;\n    $('projHours').value = FS_DEFAULTS.projectHours;\n    render();\n  });\n\n  $('copyBtn').addEventListener('click', function () {\n    var txt = $('summaryText').textContent;\n    function done() {\n      var m = $('copyMsg');\n      m.classList.remove('opacity-0');\n      setTimeout(function () { m.classList.add('opacity-0'); }, 1800);\n    }\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(txt).then(done, function () { fallbackCopy(txt); done(); });\n    } else { fallbackCopy(txt); done(); }\n  });\n  function fallbackCopy(txt) {\n    var ta = document.createElement('textarea');\n    ta.value = txt; ta.style.position = 'fixed'; ta.style.opacity = '0';\n    document.body.appendChild(ta); ta.select();\n    try { document.execCommand('copy'); } catch (e) {}\n    document.body.removeChild(ta);\n  }\n\n  // profiles (localStorage)\n  function loadProfiles() {\n    try { return JSON.parse(localStorage.getItem(FS_PROFILE_KEY) || '{}'); }\n    catch (e) { return {}; }\n  }\n  function saveProfiles(p) { try { localStorage.setItem(FS_PROFILE_KEY, JSON.stringify(p)); } catch (e) {} }\n  function refreshProfileSel() {\n    var sel = $('profileSel'), keep = sel.value, ps = loadProfiles();\n    sel.innerHTML = '<option value=\"\">Saved profiles\u2026</option>';\n    Object.keys(ps).forEach(function (name) {\n      var o = document.createElement('option'); o.value = name; o.textContent = name; sel.appendChild(o);\n    });\n    sel.value = keep;\n  }\n  $('saveProfileBtn').addEventListener('click', function () {\n    var name = $('profileName').value.trim();\n    if (!name) { $('profileName').focus(); return; }\n    var ps = loadProfiles(); ps[name] = readInputs(); saveProfiles(ps);\n    $('profileName').value = ''; refreshProfileSel(); $('profileSel').value = name;\n  });\n  $('profileSel').addEventListener('change', function () {\n    var ps = loadProfiles(), p = ps[$('profileSel').value];\n    if (!p) return;\n    INPUT_IDS.forEach(function (id) { if (p[id] !== undefined) $(id).value = p[id]; });\n    render();\n  });\n  $('delProfileBtn').addEventListener('click', function () {\n    var name = $('profileSel').value; if (!name) return;\n    var ps = loadProfiles(); delete ps[name]; saveProfiles(ps); refreshProfileSel();\n  });\n\n  // FAQ accordion\n  document.querySelectorAll('.faq-item .faq-q').forEach(function (btn) {\n    btn.addEventListener('click', function () { btn.closest('.faq-item').classList.toggle('open'); });\n  });\n\n  refreshProfileSel();\n  render();\n})();\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};